    "rättSvar": "-15/17",
    "tolerans": null,
    "självrättning": true,
    "ledtrad": "<p>Markera först rätt kvadrant. I enhetscirkeln är x-koordinaten cosinus och y-koordinaten sinus.</p>",
    "svarFormat": "uttryck",
    "traningsniva": 2,
    "arbetsinsats": 2,
    "omrTidigare": [
      "enhetscirkeln"
    ]
