    "tolerans": 0,
    "självrättning": true,
    "familjNyckel": "enhetscirkeln_formler__symmetrier_och_periodicitet_i_enhetscirkeln",
    "ledtrad": "<p>Reducera vinkeln modulo 180°, eftersom tangens har period 180°.</p>",
    "svarFormat": "numeriskt",
    "traningsniva": 2,
