    "tolerans": null,
    "självrättning": true,
    "formaga": [
      "procedur"
    ],
    "svarFormat": "uttryck",
    "ledtrad": "<p>\\(\\tan v=\\frac{\\sin v}{\\cos v}\\). Hur förhåller sig sinus och cosinus för \\(45^\\circ\\)?</p>",
    "traningsniva": 1,
    "arbetsinsats": 1,
    "spel": true,
