    "självrättning": true,
    "svarFormat": "uttryck",
    "familjNyckel": "cirkelsektorn__baglangd_sektorarea_och_radianer",
    "ledtrad": "<p>Använd \\(A=\\frac12r^2\\theta\\).</p>",
    "svarEnhet": "cm²",
    "traningsniva": 2,
    "arbetsinsats": 2,
    "omrTidigare": [
      "radianer"
    ]
