    "familjNyckel": "trig_problemlosning_2__tidpunkter_och_intervall_i_trigonometriska_modeller",
    "ledtrad": "<p>Sätt sinusdelen lika med 0 och välj nästa nollställe efter argumentet 0.</p>",
    "svarEnhet": "h",
    "traningsniva": 2,
    "arbetsinsats": 1,
    "omrTidigare": [
      "trig_modeller"
    ]
