    "rättSvar": "6*x*(x^2+1)^2*cos((x^2+1)^3)",
    "tolerans": null,
    "självrättning": true,
    "ledtrad": "<p>Arbeta utifrån och in: derivera sinus, sedan kuben, sedan \\(x^2+1\\).</p>",
    "svarFormat": "uttryck",
    "traningsniva": 3,
    "arbetsinsats": 2,
