    "rättSvar": -0.4,
    "tolerans": 1e-10,
    "självrättning": true,
    "familjNyckel": "derivata_sammansatta__kedjeregeln_for_trigonometriska_och_exponentiella_funktioner",
    "ledtrad": "<p>Skriv modellen som startvärde gånger förändringsfaktor upphöjd till tid. Isolera potensen innan du tar logaritm.</p>",
    "svarFormat": "numeriskt",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "omrTidigare": [
      "trig_derivator"
    ]
