    "formaga": [
      "procedur",
      "modellering"
    ],
    "svarFormat": "numeriskt",
    "svarEnhet": "cm²",
    "ledtrad": "<p>Kalla ena sidan \\(x\\). Hur lång är då den andra sidan?</p>",
    "traningsniva": 2,
    "arbetsinsats": 1,
    "spel": true,
    "familjNyckel": "derivata_problemlosning__geometrisk_optimering_med_derivata",
