        "etikett": "b",
        "fraga": "<p>\\(F'(x)=3x^2\\), \\(F(1)=5\\).</p>",
        "s": "<div class=\"facit-v2 facit-stegvis\"><div class=\"spel-en-del\"><ol class=\"facit-steglista\" role=\"list\"><li><div class=\"facit-matte\">\\[F=x^3+C\\],</div></li><li><p>\\(1+C=5\\): <strong>\\(F=x^3+4\\)</strong>.<br><span aria-hidden=\"true\" style=\"display:block;height:7px\"></span></p></li></ol></div></div>",
        "niva": "E",
        "poang": "1/0/0",
        "traningsniva": 2,
        "arbetsinsats": 1
