        "s": "<div class=\"facit-v2 facit-stegvis\"><ol class=\"facit-steglista\" role=\"list\"><li><div class=\"facit-berakning\"><p>Multiplicera stegvis och använd</p><div class=\"facit-matte\">\\[i^2=-1\\].</div></div></li></ol><div class=\"spel-en-del\"><div class=\"facit-del\"><span class=\"facit-mark\">b)</span><div class=\"facit-arbete\"><ol class=\"facit-steglista\" role=\"list\"><li><div class=\"facit-matte\">\\[(1+i)^3=(1+i)\\cdot2i=\\boxed{-2+2i}\\].</div></li></ol></div></div></div></div>",
        "niva": "E",
        "poang": "1/0/0",
        "traningsniva": 2,
        "arbetsinsats": 1
